### 🔹 Any Base → Decimal
```c
#include <stdio.h>
#include <math.h>
#include <string.h>

int baseToDec(char num[], int base) {
    int len = strlen(num), val = 0, power = 0;
    for (int i = len - 1; i >= 0; i--) {
        int digit;
        if (num[i] >= '0' && num[i] <= '9')
            digit = num[i] - '0';
        else
            digit = num[i] - 'A' + 10;
        val += digit * pow(base, power++);
    }
    return val;
}

int main() {
    char num[50];
    int base;
    printf("Enter number: ");
    scanf("%s", num);
    printf("Enter base (2-16): ");
    scanf("%d", &base);
    printf("Decimal = %d", baseToDec(num, base));
    return 0;
}
```

