```c
#include <stdio.h>
#include <math.h>
#include <string.h>

// Function to convert Decimal → Any Base
void decToBase(int n, int base) {
    char digits[] = "0123456789ABCDEF";
    int rem[50], i = 0;

    if (n == 0) {
        printf("Result: 0\n");
        return;
    }

    // Step 1: Divide and store remainders
    while (n > 0) {
        rem[i++] = n % base;
        n = n / base;
    }

    // Step 2: Print in reverse order
    printf("Result: ");
    for (i = i - 1; i >= 0; i--)
        printf("%c", digits[rem[i]]);
    printf("\n");
}

// Function to convert Any Base → Decimal
int baseToDec(char num[], int base) {
    int len = strlen(num);
    int value = 0, power = 1;  // power = base^0 = 1

    // Start from last digit
    for (int i = len - 1; i >= 0; i--) {
        char c = num[i];
        int digit;

        if (c >= '0' && c <= '9')
            digit = c - '0';
        else if (c >= 'A' && c <= 'F')
            digit = c - 'A' + 10;
        else if (c >= 'a' && c <= 'f')
            digit = c - 'a' + 10;
        else {
            printf("Invalid character!\n");
            return -1;
        }

        value += digit * power;
        power *= base;
    }
    return value;
}

// Main function with menu
int main() {
    int choice, base, dec;
    char num[50];

    while (1) {
        printf("\n--- BASE CONVERTER ---\n");
        printf("1. Decimal to Any Base\n");
        printf("2. Any Base to Decimal\n");
        printf("3. Exit\n");
        printf("Enter choice: ");
        scanf("%d", &choice);

        if (choice == 1) {
            printf("Enter Decimal Number: ");
            scanf("%d", &dec);
            printf("Enter Base (2–16): ");
            scanf("%d", &base);
            decToBase(dec, base);
        } 
        else if (choice == 2) {
            printf("Enter Number: ");
            scanf("%s", num);
            printf("Enter Base (2–16): ");
            scanf("%d", &base);
            int ans = baseToDec(num, base);
            if (ans != -1)
                printf("Decimal Value: %d\n", ans);
        } 
        else if (choice == 3) {
            printf("Program Ended.\n");
            break;
        } 
        else {
            printf("Invalid choice, try again!\n");
        }
    }

    return 0;
}
